module Divider (
  input  wire          io_start,
  input  wire [31:0]   io_a,
  input  wire [31:0]   io_b,
  input  wire          io_signed,
  input  wire          io_ack,
  output wire          io_busy,
  output wire          io_done,
  output wire [31:0]   io_quotient,
  output wire [31:0]   io_remainder,
  input  wire          clk,
  input  wire          reset
);

  wire       [31:0]   _zz_nextQ;
  wire       [32:0]   _zz_nextQ_1;
  wire       [31:0]   _zz_nextQ_2;
  wire       [0:0]    _zz_nextQ_3;
  wire       [31:0]   _zz_aMagIn;
  wire       [31:0]   _zz_bMagIn;
  wire       [31:0]   _zz_qFinal;
  wire       [31:0]   _zz_rFinal;
  wire       [32:0]   _zz_dSh;
  reg        [31:0]   aMagReg;
  reg        [31:0]   bMagReg;
  reg        [31:0]   aRawReg;
  reg                 signA;
  reg                 signB;
  reg                 signedOp;
  reg                 bIsZero;
  reg        [31:0]   qOut;
  reg        [31:0]   rOut;
  reg        [1:0]    state;
  reg        [5:0]    cnt;
  reg        [32:0]   rRem;
  reg        [31:0]   qAcc;
  reg        [31:0]   dSh;
  wire       [32:0]   stepRem;
  wire       [32:0]   bExt;
  wire                ge;
  wire       [32:0]   subRem;
  wire       [32:0]   nextRem;
  wire       [31:0]   nextQ;
  wire                lastStep;
  wire                aNegIn;
  wire                bNegIn;
  wire       [31:0]   aMagIn;
  wire       [31:0]   bMagIn;
  wire                qNeg;
  wire       [31:0]   qFinal;
  wire       [31:0]   rMag;
  wire       [31:0]   rFinal;
  wire       [31:0]   allOnes;
  wire       [31:0]   qRes;
  wire       [31:0]   rRes;

  assign _zz_nextQ_1 = ({1'd0,qAcc} <<< 1'd1);
  assign _zz_nextQ = _zz_nextQ_1[31:0];
  assign _zz_nextQ_3 = (ge ? 1'b1 : 1'b0);
  assign _zz_nextQ_2 = {31'd0, _zz_nextQ_3};
  assign _zz_aMagIn = (32'h0 - io_a);
  assign _zz_bMagIn = (32'h0 - io_b);
  assign _zz_qFinal = (32'h0 - nextQ);
  assign _zz_rFinal = (32'h0 - rMag);
  assign _zz_dSh = ({1'd0,dSh} <<< 1'd1);
  assign stepRem = {rRem[31 : 0],dSh[31]};
  assign bExt = {1'd0, bMagReg};
  assign ge = (bExt <= stepRem);
  assign subRem = (stepRem - bExt);
  assign nextRem = (ge ? subRem : stepRem);
  assign nextQ = (_zz_nextQ | _zz_nextQ_2);
  assign lastStep = (cnt == 6'h1f);
  assign aNegIn = io_a[31];
  assign bNegIn = io_b[31];
  assign aMagIn = ((io_signed && aNegIn) ? _zz_aMagIn : io_a);
  assign bMagIn = ((io_signed && bNegIn) ? _zz_bMagIn : io_b);
  assign qNeg = (signA ^ signB);
  assign qFinal = ((qNeg && signedOp) ? _zz_qFinal : nextQ);
  assign rMag = nextRem[31 : 0];
  assign rFinal = ((signA && signedOp) ? _zz_rFinal : rMag);
  assign allOnes = 32'hffffffff;
  assign qRes = (bIsZero ? allOnes : qFinal);
  assign rRes = (bIsZero ? aRawReg : rFinal);
  assign io_busy = (state == 2'b01);
  assign io_done = (state == 2'b10);
  assign io_quotient = qOut;
  assign io_remainder = rOut;
  always @(posedge clk or posedge reset) begin
    if(reset) begin
      state <= 2'b00;
    end else begin
      case(state)
        2'b00 : begin
          if(io_start) begin
            state <= 2'b01;
          end
        end
        2'b01 : begin
          if(bIsZero) begin
            state <= 2'b10;
          end else begin
            if(lastStep) begin
              state <= 2'b10;
            end
          end
        end
        default : begin
          if(io_start) begin
            state <= 2'b01;
          end else begin
            if(io_ack) begin
              state <= 2'b00;
            end
          end
        end
      endcase
    end
  end

  always @(posedge clk) begin
    case(state)
      2'b00 : begin
        if(io_start) begin
          aMagReg <= aMagIn;
          bMagReg <= bMagIn;
          aRawReg <= io_a;
          signA <= aNegIn;
          signB <= bNegIn;
          signedOp <= io_signed;
          bIsZero <= (io_b == 32'h0);
          rRem <= 33'h0;
          qAcc <= 32'h0;
          dSh <= aMagIn;
          cnt <= 6'h0;
        end
      end
      2'b01 : begin
        if(bIsZero) begin
          qOut <= allOnes;
          rOut <= aRawReg;
        end else begin
          if(lastStep) begin
            qOut <= qRes;
            rOut <= rRes;
          end else begin
            rRem <= nextRem;
            qAcc <= nextQ;
            dSh <= _zz_dSh[31:0];
            cnt <= (cnt + 6'h01);
          end
        end
      end
      default : begin
        if(io_start) begin
          aMagReg <= aMagIn;
          bMagReg <= bMagIn;
          aRawReg <= io_a;
          signA <= aNegIn;
          signB <= bNegIn;
          signedOp <= io_signed;
          bIsZero <= (io_b == 32'h0);
          rRem <= 33'h0;
          qAcc <= 32'h0;
          dSh <= aMagIn;
          cnt <= 6'h0;
        end
      end
    endcase
  end


endmodule

